集成到 CI 时，最稳定的是把它作为独立命令或 `multichecker` 运行。golangci-lint 的自定义 analyzer/plugin 机制随版本变化较大，应按当前版本官方文档接入，不要假设所有版本都支持同一种 `path: bin/tool` 配置。

插件化微服务骨架要把生命周期拆开：`Register` 只注册路由、依赖和中间件；`Start` 启动后台任务；`Stop` 释放资源。框架负责启动顺序、失败回滚、HTTP 入口关闭和插件逆序停止。

```go
package framework

import (
    "context"
    "errors"
    "fmt"
    "net/http"
    "os"
    "os/signal"
    "sync"
    "syscall"
    "time"
)

type Middleware func(http.Handler) http.Handler

func Chain(middlewares ...Middleware) Middleware {
    return func(next http.Handler) http.Handler {
        for i := len(middlewares) - 1; i >= 0; i-- {
            next = middlewares[i](next)
        }
        return next
    }
}

type Container struct {
    mu     sync.RWMutex
    values map[string]any
}

func NewContainer() *Container {
    return &Container{values: map[string]any{}}
}

func (c *Container) Set(name string, value any) {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.values[name] = value
}

func (c *Container) Get(name string) (any, bool) {
    c.mu.RLock()
    defer c.mu.RUnlock()
    value, ok := c.values[name]
    return value, ok
}

type Plugin interface {
    Name() string
    Register(app *App) error
    Start(ctx context.Context) error
    Stop(ctx context.Context) error
}

type App struct {
    mux         *http.ServeMux
    container   *Container
    middlewares []Middleware
    plugins     []Plugin
    server      *http.Server
}

func New(addr string) *App {
    return &App{
        mux:       http.NewServeMux(),
        container: NewContainer(),
        server:    &http.Server{Addr: addr},
    }
}

func (a *App) Use(m Middleware) { a.middlewares = append(a.middlewares, m) }
func (a *App) Handle(pattern string, h http.Handler) { a.mux.Handle(pattern, h) }
func (a *App) Provide(name string, value any) { a.container.Set(name, value) }

func (a *App) UsePlugin(plugin Plugin) error {
    if err := plugin.Register(a); err != nil {
        return fmt.Errorf("register plugin %s: %w", plugin.Name(), err)
    }
    a.plugins = append(a.plugins, plugin)
    return nil
}

func (a *App) handler() http.Handler {
    return Chain(a.middlewares...)(a.mux)
}

func (a *App) Run(ctx context.Context) error {
    ctx, stopSignals := signal.NotifyContext(ctx, os.Interrupt, syscall.SIGTERM)
    defer stopSignals()

    started := make([]Plugin, 0, len(a.plugins))
    for _, plugin := range a.plugins {
        if err := plugin.Start(ctx); err != nil {
            stopErr := stopPlugins(context.Background(), started)
            return errors.Join(fmt.Errorf("start plugin %s: %w", plugin.Name(), err), stopErr)
        }
        started = append(started, plugin)
    }

    a.server.Handler = a.handler()
    errCh := make(chan error, 1)
    go func() { errCh <- a.server.ListenAndServe() }()

    var runErr error
    select {
    case <-ctx.Done():
    case err := <-errCh:
        if !errors.Is(err, http.ErrServerClosed) {
            runErr = err
        }
    }

    shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
    defer cancel()

    if err := a.server.Shutdown(shutdownCtx); err != nil {
        runErr = errors.Join(runErr, err)
    }
    runErr = errors.Join(runErr, stopPlugins(shutdownCtx, started))
    return runErr
}

func stopPlugins(ctx context.Context, plugins []Plugin) error {
    var err error
    for i := len(plugins) - 1; i >= 0; i-- {
        if stopErr := plugins[i].Stop(ctx); stopErr != nil {
            err = errors.Join(err, fmt.Errorf("stop plugin %s: %w", plugins[i].Name(), stopErr))
        }
    }
    return err
}
```

关键点：中间件链在启动时组装一次，避免每个请求重复构建；DI 容器至少要并发安全，生产中可进一步做成类型安全 provider；启动失败要回滚已启动插件；HTTP 服务报错和关闭错误都不能跳过插件清理；插件停止顺序通常与启动顺序相反。

`net/http` 的核心抽象是 `http.Handler`：

```go
type Handler interface {
    ServeHTTP(ResponseWriter, *Request)
}
```
任何实现 `ServeHTTP(http.ResponseWriter, *http.Request)` 的类型都可以处理 HTTP 请求；普通函数可通过 `http.HandlerFunc` 适配为 Handler。

```go
package main

import (
    "errors"
    "fmt"
    "log"
    "net/http"
    "time"
)

func hello(w http.ResponseWriter, r *http.Request) {
    if r.URL.Path != "/hello" {
        http.NotFound(w, r)
        return
    }
    fmt.Fprintln(w, "hello")
}

func main() {
    mux := http.NewServeMux()
    mux.HandleFunc("GET /hello", hello)

    srv := &http.Server{
        Addr:              ":8080",
        Handler:           mux,
        ReadHeaderTimeout: 3 * time.Second,
        ReadTimeout:       10 * time.Second,
        WriteTimeout:      15 * time.Second,
        IdleTimeout:       60 * time.Second,
    }

    if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
        log.Fatal(err)
    }
}
```

生产代码优先显式创建 `ServeMux` 和 `http.Server`，不要依赖全局 `DefaultServeMux`；同时要处理 `ListenAndServe` 返回值并配置超时，否则容易被慢连接耗尽资源。

Gin 的 `Group` 用来给一组路由添加共同前缀和共同中间件，常用于 API 版本、认证区域、后台管理和多租户路由。

```go
package main

import (
    "errors"
    "log"
    "net/http"

    "github.com/gin-gonic/gin"
)

func main() {
    r := gin.New()
    r.Use(gin.Logger(), gin.Recovery())

    v1 := r.Group("/api/v1")
    {
        v1.GET("/users", listUsers)
        v1.POST("/users", createUser)
        v1.GET("/users/:id", getUser)
    }

    api := r.Group("/api")
    api.Use(JWTAuthMiddleware())
    {
        api.GET("/profile", getProfile)

        admin := api.Group("/admin")
        admin.Use(AdminOnlyMiddleware())
        admin.DELETE("/users/:id", deleteUser)
    }

    srv := &http.Server{Addr: ":8080", Handler: r}
    if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
        log.Fatal(err)
    }
}
```

分组只影响注册在该分组下的路由；中间件按注册顺序执行。`gin.Default()` 会自动带 Logger 和 Recovery，生产项目通常用 `gin.New()` 显式组合中间件，便于控制日志、恢复、认证、限流等顺序。

`Bind`、`ShouldBind` 和 `ShouldBindJSON` 的关键差异在于绑定来源和错误处理方式。

| 方法 | 来源 | 出错行为 | 建议 |
| --- | --- | --- | --- |
| `Bind` / `MustBindWith` | 按 `Content-Type` 推断 | 自动写 400 并 `Abort` | 少用，容易和自定义错误响应冲突 |
| `ShouldBind` | 按 `Content-Type` 推断 | 只返回 error | 表单/Query/JSON 混合场景使用 |
| `ShouldBindJSON` | JSON body | 只返回 error | 明确 JSON API 时使用 |

```go
type CreateUserRequest struct {
    Name  string `json:"name" binding:"required,min=2,max=50"`
    Email string `json:"email" binding:"required,email"`
    Age   int    `json:"age" binding:"gte=1,lte=150"`
}

func createUser(c *gin.Context) {
    var req CreateUserRequest
    if err := c.ShouldBindJSON(&req); err != nil {
        c.JSON(http.StatusBadRequest, gin.H{
            "code": "INVALID_ARGUMENT",
            "message": "invalid request body",
            "detail": err.Error(),
        })
        return
    }
    c.JSON(http.StatusCreated, gin.H{"ok": true})
}
```

请求 body 默认只能读一次；如果多个中间件或 handler 都需要绑定同一份 body，使用 `ShouldBindBodyWith`，同时注意 body 大小限制。错误信息不要原样暴露内部字段名时，可把 validator 的 `ValidationErrors` 转成统一错误码。

**连接池核心参数：**

```go
package main

import (
    "database/sql"
    "time"
    _ "github.com/lib/pq" // PostgreSQL 驱动
)

func newDB(dsn string) (*sql.DB, error) {
    db, err := sql.Open("postgres", dsn)
    if err != nil {
        return nil, err
    }

    // 最大打开连接数（包含空闲+使用中）
    // 0 = 无限制（危险！）
    // 建议：根据数据库最大连接数设置，预留给其他客户端
    db.SetMaxOpenConns(100)

    // 最大空闲连接数（连接池中保持的空闲连接数）
    // 应 <= MaxOpenConns
    // 设置太小：频繁建立/关闭连接；太大：空闲连接浪费资源
    db.SetMaxIdleConns(10)

    // 连接的最大生存时间（从创建起计时）
    // 防止使用长期空闲的连接（数据库服务端可能已关闭）
    // 建议：小于数据库服务端的连接超时（如 MySQL wait_timeout）
    db.SetConnMaxLifetime(30 * time.Minute)

    // 连接的最大空闲时间（连接在池中空闲的最长时间）
    // Go 1.15+ 新增
    // 比 ConnMaxLifetime 更细粒度地控制空闲连接
    db.SetConnMaxIdleTime(10 * time.Minute)

    // 验证连接是否正常
    if err := db.Ping(); err != nil {
        return nil, err
    }

    return db, nil
}
```

**参数关系图：**

```
MaxOpenConns = MaxIdleConns + 使用中的连接数
                    ↑
           空闲连接池（最多 MaxIdleConns 个）

连接生命周期：
  创建 ──[ConnMaxLifetime 超时]──→ 关闭
  空闲 ──[ConnMaxIdleTime 超时]──→ 关闭（即使未达 Lifetime）
```

**监控连接池状态：**

```go
func printDBStats(db *sql.DB) {
    stats := db.Stats()
    fmt.Printf("OpenConnections: %d\n", stats.OpenConnections)
    fmt.Printf("InUse:           %d\n", stats.InUse)
    fmt.Printf("Idle:            %d\n", stats.Idle)
    fmt.Printf("WaitCount:       %d\n", stats.WaitCount)    // 等待连接的次数
    fmt.Printf("WaitDuration:    %v\n", stats.WaitDuration) // 等待总时长
    fmt.Printf("MaxIdleClosed:   %d\n", stats.MaxIdleClosed)   // 因超过 MaxIdle 关闭的连接数
    fmt.Printf("MaxLifetimeClosed: %d\n", stats.MaxLifetimeClosed) // 因 Lifetime 关闭的连接数
}
```

**初始化客户端：**

```go
package main

import (
    "context"
    "fmt"
    "time"

    "github.com/redis/go-redis/v9"
)

var rdb *redis.Client

func initRedis() {
    rdb = redis.NewClient(&redis.Options{
        Addr:     "localhost:6379",
        Password: "", // 无密码留空
        DB:       0,  // 默认 DB

        // 连接池配置
        PoolSize:     10,              // 连接池大小
        MinIdleConns: 3,               // 最小空闲连接
        MaxIdleConns: 5,               // 最大空闲连接
        ConnMaxIdleTime: 5 * time.Minute,
        ConnMaxLifetime: 30 * time.Minute,

        // 超时配置
        DialTimeout:  5 * time.Second,  // 建立连接超时
        ReadTimeout:  3 * time.Second,  // 读超时（-1 = 禁用）
        WriteTimeout: 3 * time.Second,  // 写超时
    })
}

func main() {
    initRedis()
    ctx := context.Background()

    // Ping 测试连接
    if err := rdb.Ping(ctx).Err(); err != nil {
        panic(fmt.Sprintf("redis connect failed: %v", err))
    }

    // 基本操作
    err := rdb.Set(ctx, "key", "value", 10*time.Minute).Err()
    if err != nil {
        fmt.Printf("set error: %v\n", err)
        return
    }

    val, err := rdb.Get(ctx, "key").Result()
    if err == redis.Nil {
        fmt.Println("key not found")
    } else if err != nil {
        fmt.Printf("get error: %v\n", err)
    } else {
        fmt.Printf("key = %s\n", val)
    }

    // Hash 操作
    rdb.HSet(ctx, "user:1", "name", "Alice", "age", 30)
    name, _ := rdb.HGet(ctx, "user:1", "name").Result()
    fmt.Println(name)

    // 带超时的 context
    ctx2, cancel := context.WithTimeout(ctx, 2*time.Second)
    defer cancel()
    rdb.Set(ctx2, "temp", "data", time.Minute)
}
```

